const FILENAME: &str = "test.txt";
const EXPECTED: &[u8] = b"truncation test file\n";

fn read_file_contents(dir: &Descriptor) -> Vec<u8> {
    let file = dir
        .open_at(
            PathFlags::empty(),
            FILENAME,
            OpenFlags::empty(),
            DescriptorFlags::READ,
        )
        .expect("opening test file for reading");
    let stream = file.read_via_stream(0).expect("read stream");
    let contents = stream.blocking_read(128).expect("reading file content");
    drop(stream);
    drop(file);
    contents
}

fn main() {
    let preopens = wasi::filesystem::preopens::get_directories();
    let (dir, _) = preopens
        .iter()
        .find(|(_, path)| path == "readonly")
        .expect("locating the 'readonly' preopened directory");

    // The file should have its initial contents before we attempt anything.
    assert_eq!(
        read_file_contents(dir),
        EXPECTED,
        "file contents before attempted truncation"
    );

    // Attempt to open the file with the truncation flag but only the read flag.
    // Because truncation implies a write operation, and the directory was
    // preopened with read-only file permissions, this must be rejected with
    // ErrorCode::NotPermitted.
    let err = dir
        .open_at(
            PathFlags::empty(),
            FILENAME,
            OpenFlags::TRUNCATE,
            DescriptorFlags::READ,
        )
        .err()
        .expect("truncating open with read-only flags must fail");
    assert_eq!(err, ErrorCode::NotPermitted);

    // The file must still contain its original contents: no truncation occurred.
    assert_eq!(
        read_file_contents(dir),
        EXPECTED,
        "file contents after attempted truncation"
    );
}
